.app-header {
  background: rgba(255,255,255,.8);
  backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 10;
  padding: 0 24px;
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.app-header__logo {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--color-text);
  text-decoration: none;
}

.app-header__nav {
  display: flex;
  gap: 8px;
}

.btn-ghost {
  background: none;
  border: none;
  color: var(--color-muted);
  font-size: .875rem;
  font-weight: 500;
  padding: 6px 12px;
  border-radius: var(--radius-btn);
  cursor: pointer;
  transition: color var(--transition), background var(--transition);
  text-decoration: none;
}
.btn-ghost:hover { color: var(--color-text); background: rgba(0,0,0,.05); }

/* ── Page layout ───────────────────────────────────────────── */
.page {
  flex: 1;
  max-width: 900px;
  width: 100%;
  margin: 0 auto;
  padding: 40px 24px 80px;
}

.page__breadcrumb {
  font-size: .8125rem;
  color: var(--color-muted);
  margin-bottom: 28px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.page__breadcrumb a {
  color: var(--color-focus);
  text-decoration: none;
}
.page__breadcrumb a:hover { text-decoration: underline; }
.page__breadcrumb span { color: var(--color-border); }

/* ── Image card ────────────────────────────────────────────── */
.image-card {
  background: var(--color-surface);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr 340px;
}

@media (max-width: 680px) {
  .image-card { grid-template-columns: 1fr; }
}

/* preview pane */
.image-card__preview {
  background: #1c1c1e;
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  position: relative;
}

.image-card__preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.image-card__badge {
  position: absolute;
  top: 14px;
  left: 14px;
  background: rgba(0,0,0,.55);
  color: #fff;
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .03em;
  padding: 4px 10px;
  border-radius: 20px;
  backdrop-filter: blur(8px);
}

/* details pane */
.image-card__details {
  padding: 32px 28px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  border-left: 1px solid var(--color-border);
}

.image-card__title {
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.3;
}

.image-card__meta {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.meta-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: .875rem;
}
.meta-row__label { color: var(--color-muted); }
.meta-row__value { font-weight: 500; }

.divider {
  height: 1px;
  background: var(--color-border);
}

.image-card__tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.tag {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 20px;
  font-size: .75rem;
  font-weight: 500;
  padding: 4px 10px;
  color: var(--color-muted);
}

.image-card__actions {
  margin-top: auto;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* primary action */
.btn-primary {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: var(--color-text);
  color: #fff;
  border: none;
  border-radius: var(--radius-btn);
  font-size: .9375rem;
  font-weight: 600;
  padding: 12px 20px;
  cursor: pointer;
  transition: opacity var(--transition), transform var(--transition);
  text-decoration: none;
}
.btn-primary:hover { opacity: .85; }
.btn-primary:active { transform: scale(.98); }

