// ── Component factory ─────────────────────────────────────────
function DeleteConfirmModal({ overlayEl, dialogEl, triggerEl, onConfirm }) {
  const FOCUSABLE = 'a[href],button:not([disabled]),input,select,textarea,[tabindex]:not([tabindex="-1"])';

  function getFocusable() {
    return Array.from(dialogEl.querySelectorAll(FOCUSABLE));
  }

  function open() {
    overlayEl.classList.add('is-open');
    triggerEl.setAttribute('aria-expanded', 'true');
    dialogEl.removeAttribute('aria-hidden');
    // move focus to first focusable element inside dialog
    const focusable = getFocusable();
    if (focusable.length) focusable[0].focus();
  }

  function close() {
    overlayEl.classList.remove('is-open');
    triggerEl.setAttribute('aria-expanded', 'false');
    dialogEl.setAttribute('aria-hidden', 'true');
    triggerEl.focus();
  }

  // focus trap
  function trapFocus(e) {
    if (!overlayEl.classList.contains('is-open')) return;
    const focusable = getFocusable();
    if (!focusable.length) return;
    const first = focusable[0];
    const last  = focusable[focusable.length - 1];

    if (e.key === 'Tab') {
      if (e.shiftKey) {
        if (document.activeElement === first) { e.preventDefault(); last.focus(); }
      } else {
        if (document.activeElement === last)  { e.preventDefault(); first.focus(); }
      }
    }
    if (e.key === 'Escape') { e.preventDefault(); close(); }
  }

  // wire up events
  triggerEl.addEventListener('click', open);

  overlayEl.addEventListener('click', (e) => {
    if (e.target === overlayEl) close();
  });

  document.addEventListener('keydown', trapFocus);

  dialogEl.querySelector('[data-action="cancel"]').addEventListener('click', close);
  dialogEl.querySelector('[data-action="confirm-delete"]').addEventListener('click', () => {
    onConfirm();
    close();
  });

  return { open, close };
}

// ── Bootstrap ─────────────────────────────────────────────────
document.addEventListener('DOMContentLoaded', () => {
